#include "rinkfit/joint_jacobian_storage_census_v1.hpp"
#include <ceres/manifold.h>
#include <iostream>
using namespace rinkfit;
static void require(bool v,const char*m){if(!v)throw std::runtime_error(m);}
class Declared final:public ceres::CostFunction {bool*called_;public:Declared(int residuals,std::vector<int>sizes,bool*called):called_(called){set_num_residuals(residuals);*mutable_parameter_block_sizes()=std::move(sizes);}bool Evaluate(double const*const*,double*,double**)const override{*called_=true;return false;}};
int main(){try{bool evaluated=false;double x[4]={0},y[2]={0},z=0;ceres::Problem p;p.AddResidualBlock(new Declared(2,{4,2},&evaluated),nullptr,x,y);p.AddResidualBlock(new Declared(3,{4,1},&evaluated),nullptr,x,&z);p.SetParameterBlockConstant(y);p.SetManifold(x,new ceres::SubsetManifold(4,{1}));assert_joint_ceres_int32_storage_capacity_v1(p);require(!evaluated,"required capacity check evaluated numerical factors");const auto c=joint_jacobian_storage_census_v1(p,{{x,"physical"}});require(c.at("residual_dimensions")==5&&c.at("free_ambient_dimensions")==5&&c.at("free_tangent_dimensions")==4,"actual free/tangent census differs");require(c.at("declared_ambient_J_scalar_slots")==23&&c.at("actual_tangent_J_scalar_slots")==18&&c.at("actual_tangent_J_values_bytes")==144,"dense declared zero blocks not counted exactly");require(c.at("dense_parameter_block_diagonal_scalar_slots")==10&&c.at("potential_full_dense_row_outerproduct_multiplications")==66,"actual block normal cost estimate differs");require(c.at("ceres_int32_storage_dimensions_safe")==true&&!evaluated,"census evaluated or allocated numerical Jacobian");
 std::vector<double>large(100000,0.);ceres::Problem huge;huge.AddResidualBlock(new Declared(30000,{100000},&evaluated),nullptr,large.data());bool overflow=false;try{assert_joint_ceres_int32_storage_capacity_v1(huge);}catch(const std::exception&){overflow=true;}require(overflow&&!evaluated,"required capacity check missed 3e9 sparse index overflow");const auto limit=joint_jacobian_storage_census_v1(huge);require(limit.at("actual_tangent_J_scalar_slots")==3000000000ull&&limit.at("ceres_int32_storage_dimensions_safe")==false&&!evaluated,"int32 overflow was not rejected without allocating 24 GB J");std::cout<<"actual Jacobian storage census: free/tangent/constant blocks, dense structural zeros and 3e9 int32 guard passed without J allocation"<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
